    topThreeCoinsWithHighestAverageLoss.add(sortedTransactions[i].coinName);
  }

  print('Top three coins with highest average profit: $topThreeCoinsWithHighestAverageProfit');
  print('Top three coins with highest average loss: $topThreeCoinsWithHighestAverageLoss');
}

